INSERT INTO `freelancers` (`id_freelancer`, `usuario_id`, `categoria_id`, `profissao`, `descricao`, `experiencia`, `valor_hora`, `rede_social`) VALUES
(7, 13, 1, 'Cantor e Compositor', 'Cantor, compositor e produtor independente ligado à cena musical de Criciúma.', 'Mais de 20 anos de carreira. Com a banda Balthazar participou do Festival Criciúma Rock 2014, Circuito SESC de Música 2017 e festivais Brada Mundo e Sonora. Produziu o álbum Encantamento.', 300.00, '@cedrickmoraes'),
(8, 14, 1, 'Banda de Rock', 'Banda de Criciúma que une rock, grunge e hardcore em uma identidade própria.', '2 EPs, 1 single e 3 clipes lançados. Presença na cena autoral catarinense e shows por todo o Sul de SC.', 350.00, NULL),
(9, 15, 1, 'Banda de Rock e Blues', 'Banda de Criciúma com repertório de rock, country, blues e rock nacional.', 'Mais de quatro anos nos palcos, com material autoral e apresentações em eventos da região.', 350.00, NULL),
(10, 16, 1, 'Banda de Rock Progressivo', 'Banda de Santa Rosa do Sul com quase 8 anos de estrada em rock progressivo e pesado.', 'Finalista do Festival João Rock em São Paulo e eleita Banda Revelação em Balneário Camboriú. Dividiu o palco com Pitty, Nação Zumbi, CPM 22, Raimundos e Matanza.', 400.00, '@BarbaRalaOficial'),
(11, 17, 1, 'Cantora e Compositora', 'Cantora e compositora que transita entre a MPB e o rock autoral.', 'Álbum de estreia Terça-feira (2018) e Epifania (2020).', 250.00, '@poliana.peres'),
(12, 18, 1, 'Cantora e Compositora', 'Projeto autoral de pop rock, alternativo e emo-pop.', 'EP Unilateral, singles Silêncio e Odeio e primeiro álbum completo em gravação.', 250.00, '@fesmania'),
(13, 19, 1, 'Banda de Pop Punk', 'Banda de pop punk e rock alternativo formada em 2022.', '5 singles, 1 EP e 1 álbum lançado, com novo trabalho a caminho.', 350.00, NULL),
(14, 20, 1, 'Banda de Indie e Pop', 'Banda de Içara que começou em 2004 no Festival do Brasil.', 'Gravou 3 singles com Adair Daufembach entre 2005 e 2011. Depois de um hiato de 10 anos, voltou aos palcos com novos integrantes.', 350.00, NULL),
(15, 21, 1, 'Banda de Rock', 'Banda vencedora do Prêmio Mundial Rock 2024.', 'Premiada no cenário mundial do rock e presente nos festivais de música independente do Sul de SC.', 400.00, '@realpontozero'),
(16, 22, 1, 'Cantor e Produtor Musical', 'Cantor, compositor e produtor musical; guitarra e poesia no repertório.', 'Como artista do Selo Ambulante, lançou em 2023 os singles Da Cor do Dia e TRETA.', 250.00, NULL),
(17, 23, 1, 'Cantor de Pop e Rock', 'Projeto de pop e rock clássico inspirado em Queen, Bon Jovi, Bryan Adams e Tina Turner.', 'Dez anos de estrada com a banda, cerca de três shows por semana em casamentos, formaturas e eventos por toda Santa Catarina.', 300.00, NULL),
(18, 24, 1, 'Banda de Pop e Rock', 'Banda nascida na Cocal Fest que resgata clássicos do pop e do rock nacional.', 'Mais de uma década de shows em casamentos, pubs, festas e eventos corporativos.', 350.00, NULL),
(19, 25, 1, 'Orquestra e Música Erudita', 'Orquestra criada em parceria com a Fundação Cultural de Criciúma para levar música erudita à cidade.', 'Concertos no Espaço Cultural Angeloni, na Casa da Cultura e no Auditório Ruy Hülse da Unesc, com regência de maestros convidados.', 600.00, NULL),
(20, 26, 2, 'Fotógrafo de Eventos', 'Fotógrafo capacitado para todos os estilos de eventos, do tradicional ao artístico e de autor.', 'Profissional de Criciúma com avaliação 5.0 em plataforma de casamentos e trabalho em casamentos, formaturas e eventos sociais.', 180.00, NULL),
(21, 27, 2, 'Fotógrafos de Casamento', 'Equipe de fotografia de casamentos e eventos, um dos profissionais mais reconhecidos da região.', 'Atuando desde 2007, com avaliação 4.8 e dezenas de casamentos registrados em Criciúma e região.', 250.00, NULL),
(22, 28, 2, 'Fotógrafo de Casamentos e Família', 'Fotografia que registra sentimentos e emoções em eventos e ensaios.', 'Carreira iniciada em 2012 em eventos corporativos; especializado desde 2014 em famílias, ensaios, casamentos e formaturas. Fotos premiadas e atendimento em Criciúma e região.', 200.00, '@lukascamposfotografia'),
(23, 29, 3, 'Produtora de Vídeos', 'Soluções audiovisuais para clientes e agências de comunicação e marketing.', 'Desde 2011 com vídeo institucional, TV, propaganda em vídeo, motion graphics, After Effects e Premiere.', 250.00, NULL),
(24, 30, 3, 'Produtora de Vídeo e Podcast', 'Hub criativo com produtora profissional, duas salas de podcast e marketing digital.', 'Documentários, vídeos institucionais e de vendas, estudos de caso e podcasts para lançamentos e marcas.', 250.00, '@creativeeyesbr'),
(25, 31, 3, 'Audiovisual com Drones e FPV', 'Filmes aéreos com drones e FPV para institucionais, publicitários e eventos.', 'Nota 5.0 no Google com mais de 10 avaliações de clientes em Santa Catarina.', 300.00, '@flyahaudiovisual'),
(26, 32, 4, 'Escola de Dança', 'Escola de dança com formação em ballet e repertório clássico e contemporâneo.', 'Listada entre os grupos de dança de Criciúma pela Fundação Catarinense de Cultura e participante de mostras como o Unesc em Dança.', 120.00, NULL),
(27, 33, 4, 'Grupo de Dança Folclórica', 'Danças e cantos do folclore italiano com coreografias pesquisadas na Itália.', 'Fundado em junho de 1987. Grupos infantil e adulto, apresentações gratuitas e intercâmbio com coreógrafos italianos, como Dário Danile, em 2013.', 200.00, NULL),
(28, 34, 4, 'Companhia de Ballet', 'Companhia de dança com ballet de repertório e trabalhos solo, duo e grupo.', 'Participante do 13º Unesc em Dança com obras do repertório clássico de Marius Petipa.', 150.00, NULL),
(29, 35, 5, 'Designer Gráfico e Branding', 'Estúdio que mistura ideias, conceitos e valores em soluções visuais e comunicação digital.', 'Desde 2018 com identidade visual, jornada de marca e conteúdo criativo para marcas do Sul de Santa Catarina.', 120.00, '@cambucadesign'),
(30, 36, 5, 'Designer de Marcas', 'Especialista em criação de identidades visuais para marcas que desejam expressar sua essência.', 'Fundado em 2020 com metodologia de escuta, pesquisas e análises para identidades visuais personalizadas.', 130.00, '@est.garca'),
(31, 37, 5, 'Designer Gráfico', 'Criação de logomarca, identidade visual corporativa, catálogos, livros e anúncios.', 'Mais de 20 anos de mercado, fundador da Gêmeos Design em Criciúma e atendimento a dezenas de clientes satisfeitos.', 100.00, '@jorginhocoach');
INSERT INTO `avaliacoes` (`id`, `avaliador`, `freelancer_id`, `nota`, `comentario`, `data_avaliacao`) VALUES
  (21, 35, 7, 5, 'Cantou com a voz de quem tem mais de 20 anos de estrada. A plateia não parou de cantar junto.', '2026-04-08 12:13:00'),
  (22, 1, 7, 5, 'Ouvimos o álbum Encantamento antes do show e ele trouxe exatamente aquela atmosfera para o palco.', '2026-04-12 17:30:00'),
  (23, 2, 7, 4, 'Presença de palco ótima e conversa tranquila desde o orçamento. Vale o valor da hora cobrado.', '2026-04-16 12:47:00'),
  (24, 3, 7, 5, 'Repertório bem construído e transições suaves entre as músicas. Noite redonda de show.', '2026-04-20 17:04:00'),
  (25, 3, 8, 5, 'Grunge e hardcore bem tocados, com os clipes novos tocando ao vivo. A juventude enlouqueceu.', '2026-04-15 15:26:00'),
  (26, 4, 8, 4, 'Show bem ensaiado: os dois EPs tocaram redondo e a interação com o público foi ótima.', '2026-04-19 10:43:00'),
  (27, 5, 8, 5, 'Som pesado de verdade, sem enrolação. Contratamos para o aniversário e todo mundo elogiou.', '2026-04-23 15:00:00'),
  (28, 13, 9, 5, 'Rock, country e blues num set bem dosado. O material autoral caiu muito bem no nosso público.', '2026-04-22 18:39:00'),
  (29, 16, 9, 4, 'Banda pontual, som preparado e preço justo. Recomendo para eventos da região.', '2026-04-26 13:56:00'),
  (30, 21, 9, 5, 'Repertório variado agradou do jovem ao idoso. Ficou perfeito para a nossa festa.', '2026-04-30 18:13:00'),
  (31, 26, 10, 5, 'Rock progressivo pesado e letras inteligentes. Finalista do João Rock não é à toa: é outro nível.', '2026-04-29 11:52:00'),
  (32, 31, 10, 5, 'Dividiu o palco com Pitty e Nação Zumbi e entregou no nosso evento a mesma energia de festival grande.', '2026-05-03 16:09:00'),
  (33, 35, 10, 4, 'Show impecável e profissionalismo do primeiro e-mail ao último acorde.', '2026-05-07 11:26:00'),
  (34, 1, 10, 5, 'A entrega de som e a imagem do show estavam no nível de festival grande.', '2026-05-11 16:43:00'),
  (35, 1, 11, 5, 'A voz dela no acústico foi de arrepiar. Trouxe Terça-feira e Epifania e a plateia pediu bis.', '2026-05-06 14:05:00'),
  (36, 2, 11, 5, 'Cantora e compositora com repertório autoral de verdade. Foi o clima perfeito para a nossa noite.', '2026-05-10 09:22:00'),
  (37, 3, 11, 4, 'Muito atenciosa no preparativo e pontual na apresentação. Recomendo de olhos fechados.', '2026-05-14 14:39:00'),
  (38, 4, 12, 5, 'Pop rock com energia de EP novo. Tocou Silêncio e Odeio e o público cantou junto.', '2026-05-13 17:18:00'),
  (39, 5, 12, 4, 'Atendimento rápido, show bem ensaiado e preço justo para o que entrega.', '2026-05-17 12:35:00'),
  (40, 13, 12, 5, 'A voz tem pegada e a banda acompanha muito bem. Foi o melhor ato da nossa noite.', '2026-05-21 17:52:00'),
  (41, 16, 13, 5, 'Pop punk com cara de banda nova que já sabe o que faz. Tocaram o álbum inteiro e ninguém sentou.', '2026-05-20 10:31:00'),
  (42, 21, 13, 5, 'Desde 2022 e já com cinco singles e um EP no repertório: show maduro e divertido.', '2026-05-24 15:48:00'),
  (43, 26, 13, 4, 'Pontualidade e comunicação exemplares. Ensaio antes do evento e apresentação redonda.', '2026-05-28 10:05:00'),
  (44, 31, 13, 5, 'O novo álbum ao vivo soou ainda melhor que no estúdio. Público pediu bis.', '2026-06-01 15:22:00'),
  (45, 31, 14, 5, 'Banda com história: começou no Festival do Brasil em 2004 e voltou ao palco com tudo. Valeu a espera.', '2026-05-27 13:44:00'),
  (46, 35, 14, 4, 'O hiato de dez anos não deixou nenhum furo no som. Repertório bem ensaiado.', '2026-05-31 18:01:00'),
  (47, 1, 14, 5, 'Os singles gravados com Adair Daufembach soaram ótimos ao vivo. Nosso público de Içara amou.', '2026-06-04 13:18:00'),
  (48, 2, 15, 5, 'Vencedora do Prêmio Mundial Rock 2024 e isso se vê no palco: produção, som e presença.', '2026-06-03 16:57:00'),
  (49, 3, 15, 5, 'Fez nosso festival parecer um show grande. Recomendo para quem quer seriedade na contratação.', '2026-06-07 11:14:00'),
  (50, 4, 15, 4, 'Contratação simples, contrato cumprido e som entregue muito acima da média.', '2026-06-11 16:31:00'),
  (51, 5, 16, 5, 'Guitarra e poesia: cantou Da Cor do Dia e TRETA e prendeu a atenção do início ao fim.', '2026-06-10 09:10:00'),
  (52, 13, 16, 5, 'Artista do Selo Ambulante com voz e composição acima da média. Excelente custo-benefício.', '2026-06-14 14:27:00'),
  (53, 16, 16, 4, 'Muito transparente na negociação e pontual. Repetimos o contrato sem pensar.', '2026-06-18 09:44:00'),
  (54, 21, 16, 4, 'Guitarra bem resolvida e letra que prende. Boa conversa antes e depois do show.', '2026-06-22 14:01:00'),
  (55, 21, 17, 5, 'Levou os clássicos de Queen e Bon Jovi com uma voz que rende arrepios. Três shows por semana se explica.', '2026-06-17 12:23:00'),
  (56, 26, 17, 4, 'Banda afinada, repertório certeiro e muita animação. Nossa formatura ficou memorável.', '2026-06-21 17:40:00'),
  (57, 31, 17, 5, 'Dez anos de estrada aparecem em cada acorde. Recomendo para casamentos e eventos grandes.', '2026-06-25 12:57:00'),
  (58, 35, 18, 5, 'Resgatou os clássicos do pop e rock nacional com a energia que a Cocal Fest merecia.', '2026-06-24 15:36:00'),
  (59, 1, 18, 4, 'Mais de uma década de shows se nota na segurança do palco. Repertório para todo gosto.', '2026-06-28 10:53:00'),
  (60, 2, 18, 5, 'Banda versátil: tocou em casamento e em evento corporativo sem perder a essência.', '2026-07-02 15:10:00'),
  (61, 3, 19, 5, 'Quarenta músicos tocando juntos: a abertura no Auditório Ruy Hülse foi emocionante.', '2026-07-01 18:49:00'),
